// Runtime bindings are generated by cf workers types from cloudflare.config.ts.
// Specialize the Durable Object RPC types and add optional deployed secrets.
export interface Env extends Omit<Cloudflare.Env, "BUDGET" | "SESSIONS"> {
  BUDGET: DurableObjectNamespace<import("./index").DailyBudget>;
  SESSIONS: DurableObjectNamespace<import("./index").VoiceSession>;
  OPENAI_API_KEY?: string;
  TWILIO_ACCOUNT_SID?: string;
  TWILIO_AUTH_TOKEN?: string;
  TWILIO_API_KEY?: string;
  TWILIO_API_SECRET?: string;
  TWILIO_TWIML_APP_SID?: string;
}
